	"</div>\n"
	"<script>\n"
	"let ws=null,ok=false,base=48,hold=false,seqOn=false;const held=new Set();\n"
	"// BRIDGE: inside Syrup for the web on a phone (PHONE link): the page around it carries the messages to the computer\n"
	"const BR=window.parent!==window;let knobCb=null;\n"
	"if(BR)window.addEventListener('message',e=>{const d=e.data||{};if(d.syrupStatus){ok=d.syrupStatus=='connected';st(d.syrupStatus)}if(d.syrupKnobs&&knobCb)knobCb(d.syrupKnobs)});\n"
	"function conn(){if(BR){st('linking…');return}ws=new WebSocket('ws://'+location.host+'/ws');ws.binaryType='arraybuffer';\n"
	" ws.onopen=()=>{ok=true;st('connected')};ws.onclose=()=>{ok=false;st('reconnecting…');setTimeout(conn,1000)};ws.onerror=()=>{}}\n"
	"function st(t){document.getElementById('st').innerHTML='SYRUP REMOTE <b>'+t+'</b>'}\n"
	"function send(a){if(BR){if(ok)parent.postMessage({syrupMidi:a},'*');return}if(ok&&ws.readyState==1)ws.send(new Uint8Array(a))}\n"
	"function cc(n,v){send([0xB0,n,Math.max(0,Math.min(127,Math.round(v)))])}\n"
	"conn();\n"
	"const $=id=>document.getElementById(id);\n"
	"// pages: tap a tab or swipe sideways on the tabs\n"
	"const PAGES=['keys','chords','drums','xy','knobs'];let page='keys';\n"
	"function show(p){page=p;document.querySelectorAll('.pg').forEach(e=>e.classList.toggle('on',e.id=='p-'+p));document.querySelectorAll('#tabs button').forEach(b=>b.classList.toggle('on',b.dataset.p==p));if(p=='knobs')pollKnobs()}\n"
	"document.querySelectorAll('#tabs button').forEach(b=>b.onclick=()=>show(b.dataset.p));\n"
	"let sx=null;$('tabs').addEventListener('touchstart',e=>{sx=e.touches[0].clientX},{passive:true});\n"
	"$('tabs').addEventListener('touchend',e=>{if(sx==null)return;const dx=e.changedTouches[0].clientX-sx;sx=null;if(Math.abs(dx)>50){const i=PAGES.indexOf(page)+(dx<0?1:-1);if(i>=0&&i<PAGES.length)show(PAGES[i])}},{passive:true});\n"
	"// multitouch helper: fn(id, x, y, phase) phase 0 down, 1 move, 2 up\n"
	"function touchy(el,fn){\n"
	" el.addEventListener('touchstart',e=>{e.preventDefault();for(const t of e.changedTouches)fn(t.identifier,t.clientX,t.clientY,0)},{passive:false});\n"
	" el.addEventListener('touchmove',e=>{e.preventDefault();for(const t of e.changedTouches)fn(t.identifier,t.clientX,t.clientY,1)},{passive:false});\n"
	" const end=e=>{e.preventDefault();for(const t of e.changedTouches)fn(t.identifier,t.clientX,t.clientY,2)};\n"
	" el.addEventListener('touchend',end,{passive:false});el.addEventListener('touchcancel',end,{passive:false});\n"
	" let md=false;el.addEventListener('mousedown',e=>{md=true;fn('m',e.clientX,e.clientY,0)});window.addEventListener('mousemove',e=>{if(md)fn('m',e.clientX,e.clientY,1)});window.addEventListener('mouseup',e=>{if(md){md=false;fn('m',e.clientX,e.clientY,2)}})}\n"
	"// ---- KEYS: two octaves, multitouch, slide between keys\n"
	"const kb=$('kb');const keys=[];\n"
	"function build(){kb.innerHTML='';keys.length=0;const W=[0,2,4,5,7,9,11],B={0:1,1:3,3:6,4:8,5:10};const nw=14,ww=100/nw;\n"
	" for(let i=0;i<nw;i++){const n=base+Math.floor(i/7)*12+W[i%7];mk('k w',i*ww,ww,n)}\n"
	" for(let i=0;i<nw;i++){if(B[i%7]===undefined)continue;const n=base+Math.floor(i/7)*12+B[i%7];mk('k b',(i+1)*ww-ww*0.3,ww*0.6,n)}\n"
	" $('oct').textContent='C'+(base/12-1)}\n"
	"function mk(c,l,w,n){const d=document.createElement('div');d.className=c;d.style.left=l+'%';d.style.width=w+'%';d.dataset.n=n;kb.appendChild(d);keys.push(d);return d}\n"
	"build();\n"
	"function noteAt(x,y){const el=document.elementFromPoint(x,y);return el&&el.dataset&&el.dataset.n?+el.dataset.n:-1}\n"
	"function on(n,v){if(n<0)return;if(hold&&held.has(n)){off(n,true);return}held.add(n);send([0x90,n,v]);mark(n,true)}\n"
	"function off(n,force){if(n<0)return;if(hold&&!force)return;held.delete(n);send([0x80,n,0]);mark(n,false)}\n"
	"function mark(n,d){keys.forEach(k=>{if(+k.dataset.n==n)k.classList.toggle('down',d)})}\n"
	"function vel(y){const r=kb.getBoundingClientRect();return Math.max(30,Math.min(127,Math.round(40+87*(y-r.top)/r.height)))}\n"
	"const kt={};touchy(kb,(id,x,y,ph)=>{if(ph==0){const n=noteAt(x,y);kt[id]=n;on(n,vel(y))}else if(ph==1){const n=noteAt(x,y),o=kt[id];if(n!==o){if(!hold)off(o);kt[id]=n;if(!hold)on(n,vel(y))}}else{off(kt[id]);delete kt[id]}});\n"
	"$('od').onclick=()=>{if(base>24){panic();base-=12;build()}};$('ou').onclick=()=>{if(base<84){panic();base+=12;build()}};\n"
	"$('acid').onclick=()=>cc(104,127);\n"
	"$('hold').onclick=()=>{hold=!hold;$('hold').classList.toggle('on',hold);if(!hold)panic()};\n"
	"function panic(){held.forEach(n=>{send([0x80,n,0]);mark(n,false)});held.clear();cc(123,0)}\n"
	"$('panic').onclick=panic;\n"
	"$('pp').onclick=()=>cc(102,127);$('pn').onclick=()=>cc(103,127);\n"
	"$('seq').onclick=()=>{seqOn=!seqOn;send([seqOn?0xFA:0xFC]);$('seq').classList.toggle('on',seqOn);$('seq').textContent=seqOn?'STOP':'PLAY'};\n"
	"// ---- CHORDS: the 3DS's 7 pads (CC 105 press, 106 slide = MORPH, 0 = let go), the progression row (CC 108), the strum strip (CC 107)\n"
	"const RN=['I','ii','iii','IV','V','vi','vii°'],pads=$('pads');\n"
	"RN.forEach((r,i)=>{const d=document.createElement('div');d.className='pad';d.dataset.i=i;d.innerHTML='<i>9</i><b>'+r+'</b><i>7</i>';pads.appendChild(d)});\n"
	"function padAt(x,y){const el=document.elementFromPoint(x,y);const p=el&&el.closest?el.closest('.pad'):null;if(!p)return null;const r=p.getBoundingClientRect(),f=(y-r.top)/r.height;return{i:+p.dataset.i,band:f<1/3?2:f<2/3?1:0,el:p}}\n"
	"let padT=null,padCur=null;\n"
	"touchy(pads,(id,x,y,ph)=>{\n"
	" if(ph==0&&padT===null){padT=id;const p=padAt(x,y);if(p){padCur=p;p.el.classList.add('down');cc(105,1+p.i*3+p.band)}}\n"
	" else if(ph==1&&id===padT){const p=padAt(x,y);if(p&&padCur&&(p.i!=padCur.i||p.band!=padCur.band)){padCur.el.classList.remove('down');padCur=p;p.el.classList.add('down');cc(106,1+p.i*3+p.band)}}\n"
	" else if(ph==2&&id===padT){padT=null;if(padCur)padCur.el.classList.remove('down');padCur=null;cc(105,0)}});\n"
	"document.querySelectorAll('#prog button').forEach(b=>b.onclick=()=>{cc(108,+b.dataset.g);if(b.dataset.g=='7')b.classList.toggle('on')});\n"
	"const sm=$('strum');let sz=-1;\n"
	"touchy(sm,(id,x,y,ph)=>{if(ph==2){sz=-1;cc(107,0);return}const r=sm.getBoundingClientRect();const z=Math.max(0,Math.min(23,Math.floor((x-r.left)/r.width*24)));if(z!=sz){sz=z;cc(107,z+1)}});\n"
	"// ---- DRUMS: General MIDI notes on channel 10 (the 3DS plays them on its drum machine)\n"
	"const DR=[['KICK',36],['SNARE',38],['CLAP',39],['HAT',42],['OPEN HAT',46],['RIM',37],['LO TOM',45],['HI TOM',50],['BELL',56],['CRASH',49]],drums=$('drums');\n"
	"DR.forEach(([n,m])=>{const d=document.createElement('div');d.className='dr';d.dataset.m=m;d.textContent=n;drums.appendChild(d)});\n"
	"const dt={};touchy(drums,(id,x,y,ph)=>{if(ph==0){const el=document.elementFromPoint(x,y);const d=el&&el.closest?el.closest('.dr'):null;if(!d)return;const r=d.getBoundingClientRect(),v=Math.round(50+77*Math.max(0,Math.min(1,(y-r.top)/r.height)));send([0x99,+d.dataset.m,v]);d.classList.add('down');dt[id]=d}\n"
	" else if(ph==2&&dt[id]){send([0x89,+dt[id].dataset.m,0]);dt[id].classList.remove('down');delete dt[id]}});\n"
	"// ---- XY + sliders (CC)\n"
	"const SL=[['RES',71,10],['M1',16,0],['M2',17,0],['M3',18,0],['M4',19,0]];\n"
	"const sl=$('sl');\n"
	"function drag(el,fn){touchy(el,(id,x,y,ph)=>{if(ph<2)fn(x,y)})}\n"
	"SL.forEach(([n,c,v])=>{const s=document.createElement('div');s.className='s';s.innerHTML='<div class=\"t\"><div class=\"f\"></div></div><span>'+n+'</span>';sl.appendChild(s);\n"
	" const t=s.querySelector('.t'),f=s.querySelector('.f');const set=y=>{const r=t.getBoundingClientRect();const val=Math.max(0,Math.min(1,1-(y-r.top)/r.height));f.style.height=(val*100)+'%';cc(c,val*127)};\n"
	" f.style.height=(v/127*100)+'%';drag(t,(x,y)=>set(y))});\n"
	"const xy=$('xy'),dot=$('dot');\n"
	"drag(xy,(x,y)=>{const r=xy.getBoundingClientRect();const a=Math.max(0,Math.min(1,(x-r.left)/r.width)),b=Math.max(0,Math.min(1,1-(y-r.top)/r.height));\n"
	" dot.style.left=(a*100)+'%';dot.style.top=((1-b)*100)+'%';cc(70,a*127);cc(74,b*127)});\n"
	"dot.style.left='0%';dot.style.top='25%';\n"
	"// ---- KNOBS: what the page on the 3DS has, CC 20-27\n"
	"const kn=$('knobs'),KN=[];\n"
	"for(let k=0;k<8;k++){const d=document.createElement('div');d.className='kn';d.innerHTML='<canvas width=\"128\" height=\"128\"></canvas><span>-</span>';kn.appendChild(d);\n"
	" const o={el:d,cv:d.querySelector('canvas'),lab:d.querySelector('span'),v:-1,busy:0};KN.push(o);\n"
	" let y0=0,v0=0;touchy(d,(id,x,y,ph)=>{if(o.v<0)return;if(ph==0){y0=y;v0=o.v;o.busy=1}else if(ph==1){o.v=Math.max(0,Math.min(127,Math.round(v0+(y0-y)*0.8)));cc(20+k,o.v);knob(o)}else o.busy=0})}\n"
	"function knob(o){const c=o.cv.getContext('2d');c.clearRect(0,0,128,128);c.lineWidth=12;c.lineCap='round';c.strokeStyle='#3a2a1c';c.beginPath();c.arc(64,64,48,0.75*Math.PI,2.25*Math.PI);c.stroke();\n"
	" if(o.v>=0){c.strokeStyle='#f0a040';c.beginPath();c.arc(64,64,48,0.75*Math.PI,(0.75+1.5*o.v/127)*Math.PI);c.stroke()}}\n"
	"function pollKnobs(){if(page!='knobs')return;const use=j=>{$('kpage').textContent='KNOBS: '+j.page;j.k.forEach((a,i)=>{const o=KN[i];o.lab.textContent=a[0]||'-';if(!o.busy)o.v=a[1];knob(o)})};if(BR){knobCb=t=>{try{use(JSON.parse(t))}catch(e){}};parent.postMessage({syrupKnobs:1},'*');return}fetch('/knobs').then(r=>r.json()).then(use).catch(()=>{})}\n"
	"KN.forEach(knob);setInterval(pollKnobs,700);\n"
	"// ---- Web MIDI: forward any connected MIDI keyboard / controller (needs Chrome on a secure page, see Syrup README)\n"
	"const mi=$('midi');\n"
	"if(navigator.requestMIDIAccess){navigator.requestMIDIAccess().then(a=>{const hook=()=>{const names=[];a.inputs.forEach(i=>{names.push(i.name);i.onmidimessage=m=>{const d=m.data;if(d[0]!=0xFE)send(Array.from(d))}});mi.textContent=names.length?'MIDI IN: '+names.join(', '):'WEB MIDI ON: plug in a MIDI keyboard'};hook();a.onstatechange=hook},()=>{mi.textContent='WEB MIDI blocked by the browser'})}\n"
	"else mi.textContent='';\n"
	"\n"
	";(function(){var b=document.getElementById('along');if(!b)return;if(typeof BR!=='undefined'&&BR){b.style.display='none';return}b.onclick=function(e){e.stopPropagation();location.href='/mirror'}})();\n"
	"</script></body></html>\n";
